// 페이즈1 — Zendikar(ZEN, 2009) 세트의 미식 레어 15장. 카드는 설정 근거일 뿐이고, 지도에는 카드의 대상을
// 판타지 지도처럼 그려 넣는다(src/map/figures.ts — 바다 괴물은 바다에, 천사는 하늘 폐허 위에). 이 파일이 원본이다 — 손으로 고친다.
// - 자리는 대지 카드와 같은 규칙: 공식 근거(basis)가 닿는 곳에 두고, 닿지 않으면 이 지도의 판단(estimate — 패널에 '추정').
// - size: 그림의 가장 긴 변(지도 단위)을 대상의 크기에 맞춘다. 사람만 한 대상은 작아서, 그 지역을 확대해야 보인다.
// - nameKo 는 공식 한국어판에 인쇄된 카드 이름 (ZEN 은 한국어판이 없고, 재판의 한국어판만 있다).
// - 사람만 한 작은 대상, 또는 자리가 붐벼(기호·라벨이 몰려) 세계 지도에 두면 장소 이름을 가리는 대상은 childMap 으로
//   그 지역의 자식 지도에 넣는다. 세계 지도에는 그리지 않고(그 장소 이름 뒤에 접힌 지도 아이콘만 붙는다), 그 장소를 눌러 패널의 '지역 지도 보기'로 자식 지도를 열면 그 안에 그려진다.
import type { CardRef, ContinentId, Point, Source } from './types'

export interface PhaseCard extends CardRef {
  /** 카드 패널 주소(#card/카드id)와 그림(src/map/figures.ts)에 함께 쓰는 이름 — Scryfall 주소의 끝 부분 */
  id: string
  rarity: 'mythic' | 'rare'
  /** 카드 유형 (영문 카드 그대로) */
  typeLine: string
  /** 대상이 설정에서 무엇인지 — 공식 자료의 사실만, 한 줄 */
  subject: string
  depicts: { type: 'location'; id: string } | { type: 'continent'; id: ContinentId }
  /** 그림의 기준점(발밑·몸 가운데)을 놓을 자리 (2400×1700 지도 단위). 자식 지도에 사는 대상은 세계 지도에서의 자리(그 자식 지도 범위 안)이고, 그림은 자식 지도 그림의 subjects 자리에 그린다 */
  at: Point
  /** 그림의 가장 긴 변 (지도 단위). 자식 지도에 사는 대상의 그림 크기는 자식 지도 그림에서 정한다 */
  size: number
  /** 좌우를 뒤집어 그린다 (그림이 바깥을 보지 않게) */
  flip?: boolean
  /** 작은 대상 — 이 자식 지도(PHASE1_CHILD_MAPS 의 id)를 열었을 때만 그린다 */
  childMap?: string
  /** 대상과 자리의 공식 근거 — 대지 카드와 달리 카드 이름이 곧 지명이 아니라서 늘 적는다 */
  basis: string
  sources: Source[]
}

/** 자식 지도 — 작은 대상이 모인 지역을 큰 축척으로 따로 그린 지역 지도 (그림은 scripts/childmaps/art/<id>.js → src/map/childmaps/<id>.ts) */
export interface ChildMap {
  id: string
  /** 그 지역의 장소(locations.ts id) — 제목은 이 장소의 이름 */
  place: string
  /** 자식 지도가 그리는 범위 (세계 지도 단위) — 이 범위의 해안·장소 자리를 가져와 늘려 그린다 */
  bounds: { x0: number; y0: number; x1: number; y1: number }
  /** 해석 안내 — 공식 서술 가운데 이 지도가 그린 것과 이 지도의 판단으로 그린 것 (자식 지도 이름표에 보인다) */
  note?: string
}

